 "content": "def transform(grid):
    # Draw the successor color down any column shared by top and bottom
    # colored edge bars, stopping above the horizontal 2 barrier.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    barrier = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), h)
    top = grid[0]
    bottom = grid[-1]
    common = {c for c in range(w) if top[c] != 0 and bottom[c] != 0 and top[c] == bottom[c]}
    color = next((top[c] for c in common), None)
    if color is not None:
        for c in common:
            for r in range(1, barrier):
                if grid[r][c] == 0:
                    out[r][c] = color + 1
    return out
